<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Role;use App\Models\User;use Illuminate\Http\Request;
class UserController extends Controller{public function index(){return User::with(['role','branch'])->paginate(30);}public function store(Request$r){return response()->json(User::create($this->data($r)),201);}public function update(Request$r,User$user){$user->update($this->data($r,true));return$user->load('role');}public function destroy(User$user){$user->update(['active'=>false]);$user->tokens()->delete();return response()->noContent();}public function roles(){return Role::with('permissions')->get();}public function device(Request$r){$d=$r->validate(['push_token'=>'required|string|max:255','name'=>'required|string|max:100','platform'=>'nullable|string|max:30']);return response()->json($r->user()->devices()->updateOrCreate(['push_token'=>$d['push_token']],$d+['last_seen_at'=>now(),'active'=>true]),201);}public function notifications(Request$r){return$r->user()->notifications()->latest()->paginate(30);}public function read(Request$r,string$id){$n=$r->user()->notifications()->findOrFail($id);$n->markAsRead();return$n;}private function data(Request$r,bool$p=false):array{$s=$p?'sometimes|':'';return$r->validate(['name'=>$s.'required|string|max:150','email'=>$s.'required|email','password'=>$p?'nullable|string|min:8':'required|string|min:8','role_id'=>$s.'required|exists:roles,id','branch_id'=>'nullable|exists:branches,id','active'=>'sometimes|boolean']);}}
